    /// Arduino Printable: prints the JSON request to Serial or any Print stream.
    size_t printTo(Print& p) const {
        size_t n = p.print("{\"req\":\"");
        n += p.print(notecard_request.data());
        n += p.print("\"");
#if NOTE_API_VERSION >= NOTE_VERSION(5, 1, 1) || !defined(NOTE_API_STRICT)
        if (async) {
            n += p.print(",\"async\":");
            n += note::detail::print_json_value(p, *async);
        }
#endif
#if NOTE_API_VERSION >= NOTE_VERSION(5, 3, 1) || !defined(NOTE_API_STRICT)
        if (binary) {
            n += p.print(",\"binary\":");
            n += note::detail::print_json_value(p, *binary);
        }
#endif
        if (content) {
            n += p.print(",\"content\":");
            n += note::detail::print_json_value(p, *content);
        }
        if (file) {
            n += p.print(",\"file\":");
            n += note::detail::print_json_value(p, *file);
        }
        if (max) {
            n += p.print(",\"max\":");
            n += note::detail::print_json_value(p, *max);
        }
        if (name) {
            n += p.print(",\"name\":");
            n += note::detail::print_json_value(p, *name);
        }
        if (noteId) {
            n += p.print(",\"note\":");
            n += note::detail::print_json_value(p, *noteId);
        }
        if (offset) {
            n += p.print(",\"offset\":");
            n += note::detail::print_json_value(p, *offset);
        }
        if (payload) {
            n += p.print(",\"payload\":");
            n += note::detail::print_json_value(p, *payload);
        }
        if (route) {
            n += p.print(",\"route\":");
            n += note::detail::print_json_value(p, *route);
        }
        if (seconds) {
            n += p.print(",\"seconds\":");
            n += note::detail::print_json_value(p, *seconds);
        }
        if (status) {
            n += p.print(",\"status\":");
            n += note::detail::print_json_value(p, *status);
        }
#if NOTE_API_VERSION >= NOTE_VERSION(3, 2, 1) || !defined(NOTE_API_STRICT)
        if (total) {
            n += p.print(",\"total\":");
            n += note::detail::print_json_value(p, *total);
        }
#endif
        if (verify) {
            n += p.print(",\"verify\":");
            n += note::detail::print_json_value(p, *verify);
        }
        n += p.print("}");
        return n;
    }
#endif

